import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1230, own='cte_153.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("924.d.1.A",3,"A warehouse trainee tells a driver, calmly and with a nod toward the loading board, that his pallets will be ready at Door 6 in ten minutes. She is:","demonstrating verbal and non-verbal communication consistently in a clear, concise and effective manner",["mumbling at the floor","using vague gestures","avoiding the driver"],"Clear communication.")
H("924.d.1.A",4,"Which statement would best help a driver find the right loading door?","\"Your load is at Door 6, to the left of the office.\"",["\"It's somewhere over there.\"","\"Ask somebody, I'm busy.\"","\"Check around the building.\""],"Specific directions are clear.")
H("924.d.1.B",3,"A trainee studies a chart of late deliveries by day, notices Mondays are worst and explains the pattern to her supervisor with the numbers. She is:","analyzing, interpreting and effectively communicating information, data and observations",["hiding the chart","guessing at the cause","reading numbers aloud with no meaning"],"Data communication.")
H("924.d.1.B",4,"A good report of late-delivery data should include:","what the numbers show and what they likely mean",["only the raw numbers","only opinions","nothing about the source"],"Complete report.")
H("924.d.1.C",3,"A trainee notices a forklift driver waving his hand and pointing at a blocked aisle and moves the pallet right away. She is:","observing and interpreting verbal and nonverbal cues to enhance communication",["ignoring the driver","waiting for a written note","walking away"],"Nonverbal.")
H("924.d.1.C",4,"A coworker says he is fine but keeps rubbing his sore wrist and avoiding the lift. A good teammate would:","ask if he needs help or a break",["assume he is fine","tell him to lift anyway","say nothing and leave"],"Read cues.")
H("924.d.1.D",3,"A trainee takes notes on a dispatcher's route changes and repeats the new times back to confirm them. She is:","applying active listening skills to obtain and clarify information",["texting while listening","interrupting the dispatcher","assuming the old route"],"Active listening.")
H("924.d.1.D",4,"Repeating instructions back to the speaker is useful because it:","confirms the message was understood correctly",["wastes time","hides mistakes","replaces the instructions"],"Confirmation.")
H("924.d.2.A",3,"A trainee sees that scanner errors keep slowing the dock, so she tests the battery, then the Wi-Fi signal, then the label quality and discusses the findings with her team. She is:","employing critical-thinking skills independently and in groups to solve problems and make decisions",["guessing at the cause","giving up","blaming the scanner"],"Critical thinking.")
H("924.d.2.A",4,"When a team solves a problem together, critical thinking helps by:","testing ideas against evidence",["avoiding discussion","picking the loudest idea","ignoring results"],"Evidence.")
H("924.d.2.B",3,"A trainee sees the packing station jam every afternoon and maps each step to find where boxes pile up before suggesting a new layout. She is:","analyzing elements of a problem to develop creative and innovative solutions",["ignoring the jam","blaming the late shift","removing the station"],"Innovative solutions.")
H("924.d.2.B",4,"Mapping each step in a process helps a worker:","find where the problem begins",["avoid fixing it","hide inefficiency","add more steps"],"Map the process.")
H("924.d.2.C",3,"A trainee correctly uses terms like 'pallet jack', 'bill of lading' and 'SKU' while following a supervisor's directions. She is:","demonstrating the use of content, technical concepts and vocabulary when analyzing information and following directions",["using wrong names","avoiding the terms","guessing at directions"],"Technical vocabulary.")
H("924.d.2.C",4,"Why is it important to know the exact meaning of a term on a shipping form?","A wrong meaning can send the wrong goods to the wrong place",["It makes the form longer","It has no effect","Only managers read forms"],"Accurate terms.")
H("924.d.3.A",3,"A trainee wears her safety shoes, follows the Occupational Safety and Health Administration (OSHA) rules posted on the dock and checks that aisles are clear before moving a load. She is:","understanding and consistently following workplace safety rules and regulations",["ignoring posted rules","skipping safety shoes","blocking the aisles"],"Safety rules.")
H("924.d.3.A",4,"The Occupational Safety and Health Administration (OSHA) sets standards to:","protect workers from hazards on the job",["lower company costs","speed up deliveries","reduce staff"],"OSHA.")
H("924.d.3.B",3,"A trainee sees a worker slip on spilled oil, stays with him, alerts her supervisor and helps complete the incident report. She is:","demonstrating knowledge of procedures for reporting and handling accidents and safety incidents",["hiding the accident","leaving the scene","cleaning up first"],"Accident procedures.")
H("924.d.3.B",4,"After an accident on the dock, the first priority is to:","get help for anyone who is hurt and keep the area safe",["start a different task","fix the equipment","finish the shipment"],"First priority.")
H("924.d.4.A",3,"A trainee scans every package on her cart, keeps the area neat and asks for more work when her tasks are done. She is:","demonstrating a positive, productive work ethic by performing assigned tasks as directed",["waiting for orders","working slowly","avoiding tasks"],"Work ethic.")
H("924.d.4.A",4,"What does a productive work ethic look like during a slow hour?","Finding useful tasks without waiting to be told",["Standing idle","Hiding in the break room","Interrupting busy coworkers"],"Productive.")
H("924.d.4.B",3,"A trainee finds a box with the wrong label and weighs whether to quietly ship it or report it, deciding to report it. She is:","applying ethical reasoning to make an ethical decision",["covering up the mistake","guessing","ignoring the label"],"Ethical reasoning.")
H("924.d.4.B",4,"Which choice is the most ethical response to a mislabeled package?","Report it so it can be corrected",["Ship it anyway","Relabel it secretly","Throw it away"],"Ethical choice.")
H("924.d.4.C",3,"A trainee follows the legal limits on how much weight a cart may carry and logs her inspection each shift. She is:","complying with all applicable rules, laws and regulations in a consistent manner",["ignoring the limits","logging only sometimes","skipping inspections"],"Compliance.")
H("924.d.4.C",4,"Following load-weight regulations is important because they:","help prevent equipment failure and injuries",["slow the work","are only suggestions","favor managers"],"Load regulations.")
H("924.d.5.A",3,"A trainee in a supervised placement at a distribution center completes a pick-and-pack task, writes down what she did and reviews it with her mentor. She is:","conducting, documenting and evaluating learning activities in a supervised distribution and logistics experience",["working without supervision","skipping documentation","avoiding feedback"],"Supervised learning.")
H("924.d.5.A",4,"Why should a trainee document her learning activities?","So she can review progress and identify what to improve",["To fill empty time","To avoid feedback","To replace practice"],"Documentation.")
H("924.d.5.B",3,"A trainee learns to read inventory software reports under her mentor's guidance to reach the level needed for her chosen job. She is:","developing advanced technical knowledge and skills related to her occupational objective",["staying with the basics","avoiding the software","changing jobs"],"Advanced knowledge.")
H("924.d.5.B",4,"Advanced skills for a logistics job are best developed through:","guided, hands-on practice in a real setting",["reading only","watching only","avoiding mentors"],"Hands-on.")
H("924.d.5.C",3,"A trainee's records show her order accuracy rose from 90 percent to 98 percent over a semester. She is:","demonstrating growth of technical skill competencies",["showing no change","losing accuracy","hiding her records"],"Growth.")
H("924.d.5.C",4,"Which record best shows skill growth?","A log with accuracy scores from the start and end of the term",["A list of favorite songs","A single day's notes","An attendance sheet only"],"Show growth.")
H("924.d.5.D",3,"A trainee compares her checklist to the job requirements and sees she is strong at scanning but weak at route planning. She is:","evaluating strengths and weaknesses in technical skill proficiency",["ignoring the checklist","hiding the weakness","praising herself only"],"Evaluation.")
H("924.d.5.D",4,"Identifying a weakness is useful when it leads to:","a plan for targeted practice",["avoiding the task","hiding it from the mentor","quitting the program"],"Targeted practice.")
H("924.d.5.E",3,"A trainee saves a completed shipment log, a photo of a labeled pallet and her supervisor's note in a folder. She is:","collecting representative work samples",["discarding records","copying others' work","saving random papers"],"Work samples.")
H("924.d.5.E",4,"A student is picking items for her logistics portfolio. Which choice is the most representative of her real work?","A filled-out inventory sheet she completed herself",["A sheet a classmate finished","A blank template from the internet","A page she made up for show"],"Samples must be her own typical work.")
B.balance()
